const { parentPort, workerData: input } = require('node:worker_threads');
const { execFile } = require('node:child_process');
const { readFile } = require('node:fs/promises');
const cancelled = new Int32Array(input.cancelled);
const expired = () => Atomics.load(cancelled, 0) !== 0 || Date.now() >= input.deadline;
let child, timer;
function cancel() { Atomics.store(cancelled, 0, 1); if (child) child.kill(); }
function finish(code) { clearTimeout(timer); parentPort.postMessage(expired() ? 77 : code); parentPort.close(); }
parentPort.on('message', cancel);
(async () => {
  try {
    const bytes = await readFile(input.launcherPath);
    if (expired()) return finish(77);
    if (!bytes.includes(Buffer.from('QODER_INSTALLED_METADATA=1', 'utf16le'))) return finish(72);
    child = execFile(input.launcherPath,
      ['--sync-installed-version', input.applicationPath, input.version, String(input.deadline), input.installDirectory],
      { windowsHide: true, maxBuffer: 1024 }, error => finish(error?.code));
    if (expired()) cancel();
    else timer = setTimeout(cancel, Math.max(1, input.deadline - Date.now()));
  } catch { finish(78); }
})();
